import { seaMap, shipTuning, spawnSlots, type SeaMapDefinition, type ShipTuning, type SpawnSlot } from "@pirate-sea-race/content";

/** Static match data the step reads; it comes from `packages/content` and never changes during a match. */
export interface SimulationConfig {
  readonly map: SeaMapDefinition;
  readonly ship: ShipTuning;
  readonly spawnSlots: readonly SpawnSlot[];
}

export const defaultSimulationConfig: SimulationConfig = { map: seaMap, ship: shipTuning, spawnSlots };

/** The playable area in sub-units: positions run from 0 to these bounds inclusive, so every one lies on a tile. */
export function mapBounds(config: SimulationConfig): { maxX: number; maxY: number } {
  return {
    maxX: config.map.widthTiles * config.map.subUnitsPerTile - 1,
    maxY: config.map.heightTiles * config.map.subUnitsPerTile - 1,
  };
}
/** Integer square root (floor) by Newton's method, so no floating-point transcendental ever enters the step. */
export function isqrt(value: number): number {
  if (!Number.isSafeInteger(value) || value < 0) throw new RangeError(`isqrt needs a non-negative safe integer, got ${value}`);
  if (value < 2) return value;
  let x = value;
  let y = Math.floor((x + 1) / 2);
  while (y < x) {
    x = y;
    y = Math.floor((x + Math.floor(value / x)) / 2);
  }
  return x;
}

/** Integer division rounding toward zero. */
export function divTrunc(numerator: number, denominator: number): number {
  return Math.trunc(numerator / denominator);
}

export function clampInt(value: number, min: number, max: number): number {
  return value < min ? min : value > max ? max : value;
}
/**
 * Canonical serialization: object keys sorted, integers only for numbers, no undefined. Two equal states always
 * serialize to the same string, whatever order their keys were written in.
 */
export function canonicalize(value: unknown): string {
  if (value === null) return "null";
  switch (typeof value) {
    case "number":
      if (!Number.isSafeInteger(value)) throw new TypeError(`state numbers must be safe integers, got ${value}`);
      return String(value);
    case "string":
      return JSON.stringify(value);
    case "boolean":
      return value ? "true" : "false";
    case "object": {
      if (Array.isArray(value)) return `[${value.map(canonicalize).join(",")}]`;
      const prototype = Object.getPrototypeOf(value);
      if (prototype !== Object.prototype && prototype !== null) throw new TypeError("state must be plain data");
      const entries = Object.keys(value)
        .sort()
        .filter((key) => (value as Record<string, unknown>)[key] !== undefined)
        .map((key) => `${JSON.stringify(key)}:${canonicalize((value as Record<string, unknown>)[key])}`);
      return `{${entries.join(",")}}`;
    }
    default:
      throw new TypeError(`state cannot hold a ${typeof value}`);
  }
}

const FNV_OFFSET = 0xcbf29ce484222325n;
const FNV_PRIME = 0x100000001b3n;
const MASK_64 = 0xffffffffffffffffn;

/** 64-bit FNV-1a over the UTF-16 code units of a string, as 16 hex digits. */
export function fnv1a64(text: string): string {
  let hash = FNV_OFFSET;
  for (let index = 0; index < text.length; index++) {
    const unit = text.charCodeAt(index);
    hash = ((hash ^ BigInt(unit & 0xff)) * FNV_PRIME) & MASK_64;
    hash = ((hash ^ BigInt(unit >>> 8)) * FNV_PRIME) & MASK_64;
  }
  return hash.toString(16).padStart(16, "0");
}

/** A stable hash of the complete match state, independent of JavaScript engine and key order. */
export function hashState(state: unknown): string {
  return fnv1a64(canonicalize(state));
}
/** Movement axes enter the simulation as integers in [-AXIS_SCALE, AXIS_SCALE]. */
export const AXIS_SCALE = 1000;

/** One player's held intent for a step. `buttons` is a bit field; this feature uses movement only. */
export interface PlayerInput {
  readonly buttons: number;
  readonly moveX: number;
  readonly moveY: number;
}

export const NEUTRAL_INPUT: PlayerInput = { buttons: 0, moveX: 0, moveY: 0 };

/** Turns a protocol axis in [-1, 1] into simulation units. Out-of-range values clamp; anything non-finite is 0. */
export function quantizeAxis(axis: number): number {
  if (!Number.isFinite(axis)) return 0;
  const clamped = axis < -1 ? -1 : axis > 1 ? 1 : axis;
  return Math.round(clamped * AXIS_SCALE);
}

/** Keeps a simulation input inside its integer bounds whatever the caller passed. */
export function sanitizeInput(input: PlayerInput | undefined): PlayerInput {
  if (input === undefined) return NEUTRAL_INPUT;
  const axis = (value: number) =>
    Number.isInteger(value) ? Math.max(-AXIS_SCALE, Math.min(AXIS_SCALE, value)) : 0;
  return {
    buttons: Number.isInteger(input.buttons) ? input.buttons >>> 0 : 0,
    moveX: axis(input.moveX),
    moveY: axis(input.moveY),
  };
}
/**
 * A seeded 32-bit generator (mulberry32). Its whole state is one unsigned integer kept in the match state, so a
 * snapshot restores the random sequence exactly.
 */
export function nextRandom(state: number): { value: number; state: number } {
  const next = (state + 0x6d2b79f5) >>> 0;
  let t = next;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return { value: (t ^ (t >>> 14)) >>> 0, state: next };
}

/** An integer in [0, bound), for bounds up to 2^32. The modulo bias is negligible for the small bounds used here. */
export function nextInt(state: number, bound: number): { value: number; state: number } {
  if (!Number.isInteger(bound) || bound <= 0) throw new RangeError(`bound must be a positive integer, got ${bound}`);
  const drawn = nextRandom(state);
  return { value: drawn.value % bound, state: drawn.state };
}
import { mapBounds, type SimulationConfig } from "./config.js";
import { nextInt } from "./random.js";

/** 60 fixed steps per second: the one match clock (§15). */
export const STEPS_PER_SECOND = 60;
/** World logic runs on every third step, 20 times a second (§15). */
export const WORLD_STEP_INTERVAL = 3;

/** A ship on the sea. Every number is an integer; positions and velocities are in sub-units. */
export interface ShipState {
  readonly id: string;
  readonly slot: number;
  readonly x: number;
  readonly y: number;
  readonly vx: number;
  readonly vy: number;
  /** Eight compass headings, 0 = east, counting clockwise because y grows down. */
  readonly heading: number;
}

/** The complete match state: plain, serializable data that `hashState` covers entirely. */
export interface MatchState {
  /** Steps completed on the 60 Hz match clock. */
  readonly frame: number;
  /** World steps completed (every third frame). */
  readonly worldTick: number;
  /** The seeded generator's state. */
  readonly rng: number;
  /** In join order. */
  readonly ships: readonly ShipState[];
}

export function createMatchState(seed: number): MatchState {
  if (!Number.isInteger(seed)) throw new RangeError(`seed must be an integer, got ${seed}`);
  return { frame: 0, worldTick: 0, rng: seed >>> 0, ships: [] };
}

/** Adds a ship on a random free spawn slot. Two ships never share a slot. */
export function addShip(config: SimulationConfig, state: MatchState, id: string): MatchState {
  if (state.ships.some((ship) => ship.id === id)) throw new Error(`ship ${id} already exists`);
  const taken = new Set(state.ships.map((ship) => ship.slot));
  const free = config.spawnSlots.map((_, index) => index).filter((index) => !taken.has(index));
  if (free.length === 0) throw new Error("no free spawn slot");
  const drawn = nextInt(state.rng, free.length);
  const slot = free[drawn.value]!;
  const spawn = config.spawnSlots[slot]!;
  const half = Math.floor(config.map.subUnitsPerTile / 2);
  const { maxX, maxY } = mapBounds(config);
  const ship: ShipState = {
    id,
    slot,
    x: Math.min(spawn.tileX * config.map.subUnitsPerTile + half, maxX),
    y: Math.min(spawn.tileY * config.map.subUnitsPerTile + half, maxY),
    vx: 0,
    vy: 0,
    heading: 0,
  };
  return { ...state, rng: drawn.state, ships: [...state.ships, ship] };
}

export function removeShip(state: MatchState, id: string): MatchState {
  return { ...state, ships: state.ships.filter((ship) => ship.id !== id) };
}

/** A position as the tile it lies on plus the sub-unit offset inside that tile. */
export function toTilePosition(config: SimulationConfig, x: number, y: number) {
  const size = config.map.subUnitsPerTile;
  return {
    tileX: Math.floor(x / size),
    tileY: Math.floor(y / size),
    offsetX: x % size,
    offsetY: y % size,
  };
}
import { mapBounds, type SimulationConfig } from "./config.js";
import { clampInt, divTrunc, isqrt } from "./fixed.js";
import { AXIS_SCALE, sanitizeInput, type PlayerInput } from "./input.js";
import { WORLD_STEP_INTERVAL, type MatchState, type ShipState } from "./state.js";

/** Held inputs by ship id; a ship without an entry is neutral. */
export type StepInputs = Readonly<Record<string, PlayerInput>>;

export function isWorldStep(frame: number): boolean {
  return frame % WORLD_STEP_INTERVAL === 0;
}

/**
 * Advances the match clock by one 60 Hz step and returns the new state. World logic (ship movement) runs only when
 * the new frame is a multiple of WORLD_STEP_INTERVAL. The input state is never mutated.
 */
export function step(config: SimulationConfig, state: MatchState, inputs: StepInputs): MatchState {
  const frame = state.frame + 1;
  if (!isWorldStep(frame)) return { ...state, frame };
  return {
    ...state,
    frame,
    worldTick: state.worldTick + 1,
    ships: state.ships.map((ship) => moveShip(config, ship, sanitizeInput(inputs[ship.id]))),
  };
}

function moveShip(config: SimulationConfig, ship: ShipState, input: PlayerInput): ShipState {
  const speed = config.ship.speedSubUnitsPerWorldStep;
  const { moveX, moveY } = input;
  // Diagonals are normalised with an integer square root so full throttle is the same speed in every direction.
  const length = isqrt(moveX * moveX + moveY * moveY);
  const divisor = Math.max(length, AXIS_SCALE);
  const vx = divTrunc(speed * moveX, divisor);
  const vy = divTrunc(speed * moveY, divisor);
  const { maxX, maxY } = mapBounds(config);
  return {
    ...ship,
    x: clampInt(ship.x + vx, 0, maxX),
    y: clampInt(ship.y + vy, 0, maxY),
    vx,
    vy,
    heading: vx === 0 && vy === 0 ? ship.heading : headingOf(vx, vy),
  };
}

/** Headings by the signs of the velocity, at index `(sy + 1) * 3 + (sx + 1)`. Built once, not per call. */
const HEADINGS: readonly number[] = [5, 6, 7, 4, 0, 0, 3, 2, 1];

/** Eight-way heading from the signs of the velocity (0 = east, clockwise with y down). */
function headingOf(vx: number, vy: number): number {
  return HEADINGS[(Math.sign(vy) + 1) * 3 + (Math.sign(vx) + 1)] ?? 0;
}
import { z } from "zod";
import { formatIssues, type ValidationResult } from "./rules.js";

/** How the attacker stands after the defender blocks (§8): a frame advantage, or one of the table's special cases. */
export const onBlockSchema = z.discriminatedUnion("kind", [
  /** Negative is minus: "Minus 12" is `{ kind: "frames", advantage: -12 }`. */
  z.strictObject({ kind: z.literal("frames"), advantage: z.int() }),
  z.strictObject({ kind: z.literal("spacing-dependent") }),
  z.strictObject({ kind: z.literal("unguardable") }),
]);

/**
 * One row of the baseline frame budgets (§8), in 60 Hz frames. `active` is `"projectile-life"` when the hit lives on
 * a projectile rather than the fighter.
 */
export const moveTimingSchema = z
  .strictObject({
    id: z.string().regex(/^[a-z][a-z0-9-]*$/),
    name: z.string().min(1),
    startup: z.int().positive(),
    active: z.union([z.int().positive(), z.literal("projectile-life")]),
    recovery: z.int().nonnegative(),
    onBlock: onBlockSchema,
  })
  .superRefine((move, ctx) => {
    // Advantage on block is blockstun minus the attacker's remaining active and recovery frames. Blockstun is never
    // negative, so the attacker can never be more minus than active + recovery.
    if (move.onBlock.kind === "frames" && typeof move.active === "number" && move.onBlock.advantage < -(move.active + move.recovery)) {
      ctx.addIssue({
        code: "custom",
        path: ["onBlock", "advantage"],
        message: `minus ${-move.onBlock.advantage} on block exceeds active + recovery (${move.active + move.recovery} frames)`,
      });
    }
  });

export type MoveTiming = z.infer<typeof moveTimingSchema>;

export const baselineFrameBudgets = [
  { id: "jab", name: "Jab", startup: 7, active: 3, recovery: 12, onBlock: { kind: "frames", advantage: -2 } },
  { id: "heavy-mid", name: "Heavy mid", startup: 18, active: 4, recovery: 24, onBlock: { kind: "frames", advantage: -12 } },
  { id: "low-sweep", name: "Low sweep", startup: 20, active: 3, recovery: 26, onBlock: { kind: "frames", advantage: -15 } },
  { id: "projectile-special", name: "Projectile special", startup: 22, active: "projectile-life", recovery: 30, onBlock: { kind: "spacing-dependent" } },
  { id: "throw", name: "Throw", startup: 12, active: 2, recovery: 24, onBlock: { kind: "unguardable" } },
] as const satisfies readonly MoveTiming[];

export function validateMoveTiming(candidate: unknown): ValidationResult<MoveTiming> {
  const parsed = moveTimingSchema.safeParse(candidate);
  return parsed.success ? { ok: true, value: parsed.data } : { ok: false, issues: formatIssues(parsed.error) };
}

/** Validates a whole table: every row, and no id used twice. */
export function validateFrameBudgets(candidate: unknown): ValidationResult<MoveTiming[]> {
  const parsed = z.array(moveTimingSchema).safeParse(candidate);
  if (!parsed.success) return { ok: false, issues: formatIssues(parsed.error) };
  const seen = new Set<string>();
  const issues: string[] = [];
  for (const move of parsed.data) {
    if (seen.has(move.id)) issues.push(`${move.id}: duplicate move id`);
    seen.add(move.id);
  }
  return issues.length > 0 ? { ok: false, issues } : { ok: true, value: parsed.data };
}

