  if (!Number.isSafeInteger(candidate.frame) || candidate.frame! < 0 || !Array.isArray(candidate.fighters) || candidate.fighters.length !== 2) {
    throw new TypeError("the snapshot is not a duel state");
  }
  return snapshotDuel(candidate as DuelState);
}
EOF
